package com.hssa.auth.entity; import jakarta.persistence.*; import lombok.AllArgsConstructor; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import org.hibernate.annotations.CreationTimestamp; import java.time.LocalDateTime; import java.util.UUID; @Entity @Table(name = "login_history", schema = "auth") @Getter @Setter @NoArgsConstructor @AllArgsConstructor public class LoginHistory { @Id @GeneratedValue(strategy = GenerationType.UUID) @Column(name = "id", updatable = false, nullable = false) private UUID id; @ManyToOne(fetch = FetchType.LAZY) @JoinColumn(name = "user_id") private User user; @Column(name = "email") private String email; @Column(name = "login_time", nullable = false) private LocalDateTime loginTime = LocalDateTime.now(); @Column(name = "logout_time") private LocalDateTime logoutTime; @Column(name = "ip_address") private String ipAddress; @Column(name = "user_agent", columnDefinition = "TEXT") private String userAgent; @Column(name = "browser", length = 100) private String browser; @Column(name = "browser_version", length = 100) private String browserVersion; @Column(name = "operating_system", length = 100) private String operatingSystem; @Column(name = "device_type", length = 100) private String deviceType; @Column(name = "login_success", nullable = false) private boolean loginSuccess; @Column(name = "failure_reason", length = 255) private String failureReason; @Column(name = "country", length = 100) private String country; @Column(name = "city", length = 100) private String city; @Column(name = "latitude") private Double latitude; @Column(name = "longitude") private Double longitude; @CreationTimestamp @Column(name = "created_at", nullable = false, updatable = false) private LocalDateTime createdAt; }
